using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using GenesisMesh;
using NSec.Cryptography;
using Xunit;

namespace GenesisMesh.Sdk.Tests;

/// <summary>
/// Shared conformance suite <c>grants</c> (v1.6.0), generated by the Python reference
/// (genesismesh/conformance/generate_vectors.py grants) and copied here unchanged. This SDK runs the vectors of what
/// it verifies: the signed forms of the grant records and the revocation feed, and their signatures as received.
/// Envelopes, issuance, uses and evidence exports are checked by the core and the TypeScript and Rust SDKs. Then a
/// grant's NA signature against a key history.
/// </summary>
public class GrantsTests
{
    private static readonly string SuitePath = Path.Combine(AppContext.BaseDirectory, "testdata", "conformance", "grants.json");
    private static readonly HashSet<string> KindsRun = new() { "canonical_form", "verify_record", "envelope_parameter", "envelope", "use" };

    /// <summary>
    /// <c>issuance</c> is the NA's own decision (an SDK never issues a grant); <c>verify_export</c>: an export's grant
    /// entries are verified offline in a later step of 1.9.0.
    /// </summary>
    private static readonly HashSet<string> KindsNotRun = new() { "issuance", "verify_export" };

    private static JsonElement.ArrayEnumerator Vectors()
    {
        var root = JsonDocument.Parse(File.ReadAllText(SuitePath)).RootElement;
        Assert.Equal("grants", root.GetProperty("suite").GetString());
        return root.GetProperty("vectors").EnumerateArray();
    }

    private static JsonElement Vector(string id) => Vectors().Single(v => v.GetProperty("id").GetString() == id);

    public static IEnumerable<object[]> VectorIds() => Vectors()
        .Where(v => !KindsNotRun.Contains(v.GetProperty("kind").GetString()!))
        .Select(v => new object[] { v.GetProperty("id").GetString()! });

    internal static ConformanceReceipt Receipt() => ConformanceReceipts.For(
        "grants", typeof(GrantsTests), nameof(ReproducesTheReferenceOutcome), VectorIds(), KindsRun, KindsNotRun);

    [Fact]
    public void EveryKindIsRunOrListedAsNotRun() => ConformanceReceipts.Record(Receipt());

    [Theory]
    [MemberData(nameof(VectorIds))]
    public void ReproducesTheReferenceOutcome(string id)
    {
        var v = Vector(id);
        var kind = v.GetProperty("kind").GetString();
        if (kind is "envelope_parameter" or "envelope" or "use")
        {
            Assert.Equal(Canonical.FromJson(v.GetProperty("expected").GetRawText()), Canonical.FromJson(RuleOutcome(kind, v.GetProperty("input"))));
            return;
        }
        var model = v.GetProperty("model").GetString()!;
        var record = v.GetProperty("record");
        object got;
        switch (kind)
        {
            case "canonical_form":
                {
                    var body = OfflineVerifier.ReceivedCanonical(model, record);
                    got = new Dictionary<string, object>
                    {
                        ["canonical"] = body,
                        ["digest"] = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(body))).ToLowerInvariant(),
                    };
                    break;
                }
            case "verify_record":
                got = new Dictionary<string, object>
                {
                    ["valid"] = OfflineVerifier.SignedAsReceived(model, record, new[] { v.GetProperty("public_key").GetString()! }),
                };
                break;
            default:
                throw new InvalidOperationException($"vector kind {v.GetProperty("kind").GetString()} is not run");
        }
        Assert.Equal(Canonical.FromJson(v.GetProperty("expected").GetRawText()), Canonical.FromJson(JsonSerializer.Serialize(got)));
    }

    /// <summary>An envelope, a parameter or a use as the grants rules read it, in the vector's terms.</summary>
    private static string RuleOutcome(string kind, JsonElement input)
    {
        switch (kind)
        {
            case "envelope_parameter":
                {
                    // A parameter given as text is read as every implementation reads JSON (2^64 is refused).
                    JsonElement parameter;
                    if (input.TryGetProperty("parameter_json", out var text))
                    {
                        try
                        {
                            using var doc = StrictJsonReader.Parse(text.GetString()!);
                            parameter = doc.RootElement.Clone();
                        }
                        catch (StrictJsonException)
                        {
                            return """{"valid": false}""";
                        }
                    }
                    else
                    {
                        parameter = input.GetProperty("parameter");
                    }
                    return GrantRules.Parameter(parameter, out _) is { } read
                        ? "{\"valid\": true, \"normalized\": " + read.ToJson() + "}"
                        : """{"valid": false}""";
                }
            case "envelope":
                {
                    var envelope = new JsonObject();
                    foreach (var p in input.GetProperty("envelope").EnumerateObject())
                        envelope[p.Name] = JsonNode.Parse(GrantRules.Parameter(p.Value, out var problem)?.ToJson() ?? throw new InvalidOperationException(problem));
                    var within = GrantRules.EnvelopeProblem(JsonSerializer.SerializeToElement(envelope), input.GetProperty("request_parameters")) is null;
                    return JsonSerializer.Serialize(new Dictionary<string, bool> { ["within"] = within });
                }
            default:
                {
                    static string? Str(JsonElement o, string name) =>
                        o.TryGetProperty(name, out var v) && v.ValueKind == JsonValueKind.String ? v.GetString() : null;
                    var use = input.GetProperty("use").Deserialize<GrantExecutionEvidence>()!;
                    var grant = input.TryGetProperty("grant", out var g) && g.ValueKind == JsonValueKind.Object ? g.Deserialize<CapabilityGrant>() : null;
                    var previous = input.TryGetProperty("previous", out var p) && p.ValueKind == JsonValueKind.Object
                        ? new PreviousUse(Str(p, "executed_at")!, Str(p, "time_token_issued_at")!)
                        : null;
                    var head = input.TryGetProperty("token_head", out var h) && h.ValueKind == JsonValueKind.Object
                        ? new TokenHead(Str(h, "digest")!, Str(h, "executed_at")!)
                        : null;
                    var found = GrantRules.UseProblem(use, new UseCheck
                    {
                        Grant = grant,
                        Previous = previous,
                        Admitted = input.TryGetProperty("admitted", out var a) && a.ValueKind == JsonValueKind.Number ? a.GetInt32() : null,
                        TokenHead = head,
                        TokenKeys = input.GetProperty("na_public_keys").EnumerateArray().Select(k => k.GetString()!).ToList(),
                        RawToken = input.GetProperty("use").GetProperty("time_token"),
                        RevokedAt = Str(input, "revoked_at"),
                        RecordedAt = Str(input, "recorded_at"),
                    });
                    return JsonSerializer.Serialize(new Dictionary<string, string?> { ["code"] = found?.Code });
                }
        }
    }

    [Theory]
    [InlineData("signature-feed-with-grants")]
    [InlineData("signature-feed-without-grants")]
    public void ARevocationFeedWithOrWithoutGrantsIsAKnownSignedForm(string id)
    {
        // v1.6.0: with grants on, the NA's feed lists revoked_grant_ids; while they are off it keeps its 1.5 form.
        var record = Vector(id).GetProperty("record");
        Assert.Empty(StrictFields.UnknownFields("SovereignRevocationFeed", record));
        Assert.Empty(StrictFields.NonCanonicalFields("SovereignRevocationFeed", record));
    }

    // ── VerifyCapabilityGrant ──────────────────────────────────────────────

    private static readonly JsonElement Signed = Vector("signature-CapabilityGrant-signer");
    private static readonly string SignerKey = Signed.GetProperty("public_key").GetString()!;
    private static readonly string OtherKey = Vector("signature-CapabilityGrant-other-key").GetProperty("public_key").GetString()!;
    private static string GrantJson => Signed.GetProperty("record").GetRawText();

    private static string Verify(string grantJson, NAKeyHistory history)
    {
        var r = OfflineVerifier.VerifyCapabilityGrant(grantJson, history);
        Assert.Equal(r.Reason == "accepted", r.Valid);
        Assert.False(string.IsNullOrEmpty(r.GrantId));
        return r.Reason;
    }

    /// <summary>The suite's grant with a change, signed again by <paramref name="key"/>.</summary>
    private static string SignedAgain(Key key, Action<JsonObject>? change = null)
    {
        var grant = JsonNode.Parse(GrantJson)!.AsObject();
        change?.Invoke(grant);
        using var doc = JsonDocument.Parse(grant.ToJsonString());
        var body = Encoding.UTF8.GetBytes(OfflineVerifier.ReceivedCanonical("CapabilityGrant", doc.RootElement));
        grant["signature"] = new JsonObject
        {
            ["key_id"] = "na-key",
            ["sig"] = Convert.ToBase64String(SignatureAlgorithm.Ed25519.Sign(key, body)),
        };
        return grant.ToJsonString();
    }

    [Fact]
    public void TheNAsGrantVerifies()
    {
        Assert.Equal("accepted", Verify(GrantJson, NAKeyHistory.ValidAlways(new[] { SignerKey })));
        Assert.Equal("invalid_signature", Verify(GrantJson, NAKeyHistory.ValidAlways(new[] { OtherKey })));
        var unsigned = JsonNode.Parse(GrantJson)!.AsObject();
        unsigned.Remove("signature");
        Assert.Equal("missing_signature", Verify(unsigned.ToJsonString(), NAKeyHistory.ValidAlways(new[] { SignerKey })));
        Assert.Throws<ArgumentNullException>(() => OfflineVerifier.VerifyCapabilityGrant(GrantJson, (NAKeyHistory)null!));
        Assert.Throws<ArgumentNullException>(() => OfflineVerifier.VerifyCapabilityGrant(GrantJson, (IReadOnlyList<string>)null!));
    }

    [Theory]
    [InlineData(-3600, "accepted")]
    [InlineData(3600, "na_key_not_valid_at_time")]
    public void TheKeyValidAtIssuedAtSignsTheGrant(int successionSeconds, string expected)
    {
        // The signer took over from another key an hour before the grant was issued, or takes over an hour after.
        var issuedAt = OfflineVerifier.ParseTimestamp(Signed.GetProperty("record").GetProperty("issued_at").GetString()!);
        var at = issuedAt.AddSeconds(successionSeconds);
        var history = new NAKeyHistory("sovereign-c", null, new[]
        {
            new NAKey(1, "na-1", OtherKey, null, at, null, false),
            new NAKey(2, "na-2", SignerKey, at, null, null, false),
        });
        Assert.Equal(expected, Verify(GrantJson, history));
    }

    [Fact]
    public void AGrantIsStrict()
    {
        // A signed field this SDK does not know, or a form the reference does not write, is refused by name when
        // the signature verifies.
        var key = Key.Import(SignatureAlgorithm.Ed25519, Enumerable.Repeat((byte)0x61, 32).ToArray(), KeyBlobFormat.RawPrivateKey);
        var keys = NAKeyHistory.ValidAlways(new[] { Convert.ToBase64String(key.PublicKey.Export(KeyBlobFormat.RawPublicKey)) });
        Assert.Equal("accepted", Verify(SignedAgain(key), keys));
        Assert.Equal("unknown_field", Verify(SignedAgain(key, g => g["delegable"] = true), keys));
        Assert.Equal("non_canonical_form", Verify(SignedAgain(key, g => g["issued_at"] = "2026-01-01T00:00:00+00:00"), keys));
        // A field the reference fills when absent: read, but not in the form it writes.
        Assert.Equal("non_canonical_form", Verify(SignedAgain(key, g => g.Remove("parameter_envelope")), keys));
        // 1.9.0: a field the reference requires, missing, or a validity longer than 24 hours: no grant at all.
        Assert.Equal("malformed", Verify(SignedAgain(key, g => g.Remove("max_uses_per_time_token")), keys));
        Assert.Equal("malformed", Verify(SignedAgain(key, g => g["valid_until"] = "2099-01-01T00:00:00Z"), keys));
        // The budget's bounds: 10,000 uses, 1,000 per time token.
        Assert.Equal("accepted", Verify(SignedAgain(key, g => g["max_uses"] = 10000), keys));
        Assert.Equal("malformed", Verify(SignedAgain(key, g => g["max_uses"] = 10001), keys));
        Assert.Equal("accepted", Verify(SignedAgain(key, g => g["max_uses_per_time_token"] = 1000), keys));
        Assert.Equal("malformed", Verify(SignedAgain(key, g => g["max_uses_per_time_token"] = 1001), keys));
    }
}
